        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2 - [fastq1, fastq2], index, fasta, true - stub") {

        options "-stub"

        when {
